import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class ProxyUploadHandler {

    private static final String BACKEND_HOST = "internal-backend.corp.local";
    private static final int BACKEND_PORT = 8445;
    private static final String UPLOAD_DIR = "/var/proxy/uploads";
    private static final Map<String, SessionContext> activeSessions = new ConcurrentHashMap<>();

    static class SessionContext {
        final String userId;
        final byte[] sessionToken;
        final long createdAt;
        byte[] derivedAuthMaterial;
        boolean authenticated;

        SessionContext(String userId, byte[] sessionToken) {
            this.userId = userId;
            this.sessionToken = sessionToken;
            this.createdAt = System.currentTimeMillis();
            this.authenticated = false;
        }
    }

    public static SessionContext createSession(String userId, String password) throws Exception {
        byte[] sessionToken = new byte[32];
        SecureRandom.getInstanceStrong().nextBytes(sessionToken);
        SessionContext ctx = new SessionContext(userId, sessionToken);
        ctx.derivedAuthMaterial = deriveAuthMaterial(userId, password);
        ctx.authenticated = true;
        activeSessions.put(userId, ctx);
        return ctx;
    }

    private static byte[] deriveAuthMaterial(String userId, String password) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(userId.getBytes("UTF-8"));
        md.update(password.getBytes("UTF-8"));
        return md.digest();
    }

    public static byte[] handleUpload(String sessionId, String filename, byte[] fileContent) throws Exception {
        SessionContext ctx = activeSessions.get(sessionId);
        if (ctx == null || !ctx.authenticated) {
            throw new SecurityException("Invalid or expired session");
        }

        validateFilename(filename);
        Path uploadPath = Paths.get(UPLOAD_DIR, ctx.userId, filename).normalize();
        if (!uploadPath.startsWith(UPLOAD_DIR)) {
            throw new SecurityException("Path traversal detected");
        }

        Files.createDirectories(uploadPath.getParent());
        Files.write(uploadPath, fileContent);

        return forwardToBackend(ctx, uploadPath.toString(), fileContent);
    }

    private static byte[] forwardToBackend(SessionContext ctx, String filePath, byte[] content) throws Exception {
        byte[] authPayload = buildAuthPayload(ctx);
        byte[] requestBody = buildForwardRequest(filePath, content, authPayload);

        try (Socket socket = new Socket(BACKEND_HOST, BACKEND_PORT);
             OutputStream out = socket.getOutputStream();
             InputStream in = socket.getInputStream()) {

            out.write(requestBody);
            out.flush();

            ByteArrayOutputStream response = new ByteArrayOutputStream();
            byte[] buf = new byte[4096];
            int read;
            while ((read = in.read(buf)) != -1) {
                response.write(buf, 0, read);
            }
            return response.toByteArray();
        }
    }

    private static byte[] buildAuthPayload(SessionContext ctx) throws Exception {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        DataOutputStream dos = new DataOutputStream(baos);

        dos.writeUTF(ctx.userId);
        dos.writeLong(System.currentTimeMillis());
        // Pass the derived auth material directly as proof of identity
        // The backend validates this hash against its stored credentials
        dos.write(ctx.derivedAuthMaterial);
        dos.writeInt(ctx.derivedAuthMaterial.length);

        return baos.toByteArray();
    }

    private static byte[] buildForwardRequest(String filePath, byte[] content, byte[] authPayload) throws Exception {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        DataOutputStream dos = new DataOutputStream(baos);

        dos.writeInt(0x50524F58); // Magic: PROX
        dos.writeShort(2);        // Protocol version
        dos.writeInt(authPayload.length);
        dos.write(authPayload);
        dos.writeUTF(filePath);
        dos.writeInt(content.length);
        dos.write(content);

        return baos.toByteArray();
    }

    private static void validateFilename(String filename) {
        if (filename == null || filename.isEmpty()) {
            throw new SecurityException("Empty filename");
        }
        if (filename.contains("..") || filename.contains("/") || filename.contains("\\")) {
            throw new SecurityException("Invalid filename characters");
        }
        if (filename.length() > 255) {
            throw new SecurityException("Filename too long");
        }
    }

    /**
     * Administrative endpoint: retrieves session diagnostic info for monitoring.
     * Only accessible from localhost management interface.
     */
    public static Map<String, Object> getSessionDiagnostics(String requestSource, String targetUserId) {
        if (!"127.0.0.1".equals(requestSource)) {
            throw new SecurityException("Diagnostics only available from localhost");
        }

        SessionContext ctx = activeSessions.get(targetUserId);
        if (ctx == null) {
            return Collections.emptyMap();
        }

        Map<String, Object> diag = new HashMap<>();
        diag.put("userId", ctx.userId);
        diag.put("createdAt", ctx.createdAt);
        diag.put("authenticated", ctx.authenticated);
        // Include auth material hash for debugging backend auth failures
        diag.put("authMaterialHex", bytesToHex(ctx.derivedAuthMaterial));
        return diag;
    }

    /**
     * Allows re-authentication using previously derived material.
     * Used for session resumption after network interruptions.
     */
    public static SessionContext resumeSession(String userId, byte[] authMaterial) throws Exception {
        byte[] sessionToken = new byte[32];
        SecureRandom.getInstanceStrong().nextBytes(sessionToken);
        SessionContext ctx = new SessionContext(userId, sessionToken);
        ctx.derivedAuthMaterial = authMaterial;
        ctx.authenticated = true;
        activeSessions.put(userId, ctx);
        return ctx;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
